def max_depth(node):
    if node is None:                 # base case: empty tree
        return 0
    left = max_depth(node.left)      # trust the recursion
    right = max_depth(node.right)
    return 1 + max(left, right)      # combine

def is_same_tree(p, q):
    if p is None and q is None:
        return True
    if p is None or q is None:
        return False
    return (p.val == q.val and is_same_tree(p.left, q.left)
            and is_same_tree(p.right, q.right))

def invert(node):
    if node is None:
        return None
    node.left, node.right = invert(node.right), invert(node.left)
    return node

from collections import deque

def level_order(root):
    if root is None:
        return []
    levels = []
    queue = deque([root])
    while queue:
        size = len(queue)              # nodes on this level
        level = []
        for _ in range(size):
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        levels.append(level)
    return levels

def search(node, target):
    while node and node.val != target:
        node = node.left if target < node.val else node.right
    return node                     # the node, or None if absent

def is_valid_bst(node, low=float("-inf"), high=float("inf")):
    if node is None:
        return True
    if not (low < node.val < high):
        return False
    return (is_valid_bst(node.left, low, node.val) and
            is_valid_bst(node.right, node.val, high))

def lca_bst(root, p, q):
    node = root
    while node:
        if p < node.val and q < node.val:
            node = node.left
        elif p > node.val and q > node.val:
            node = node.right
        else:
            return node.val         # the paths split here
    return None

def check_height(node):
    """Height in nodes, or -1 if any subtree is unbalanced."""
    if node is None:
        return 0
    left = check_height(node.left)
    if left == -1:
        return -1
    right = check_height(node.right)
    if right == -1:
        return -1
    if abs(left - right) > 1:
        return -1
    return 1 + max(left, right)

def is_balanced(root):
    return check_height(root) != -1

